#!/usr/bin/env python3
"""Fixture builder for tests/test_check_builders.py.

Turns config/status_choices.json into src/generated/status_choices.yml, the way a
per-component builder turns its input into the YAML-format solution source (plan
section 5.6). Paths are relative to the project root, which is where
check_builders.py runs every builder from.
"""
import json
from pathlib import Path

SOURCE = Path("config/status_choices.json")
OUTPUT = Path("src/generated/status_choices.yml")
FIRST_VALUE = 100000000  # Dataverse choice values start from the publisher's prefix


def main() -> None:
    spec = json.loads(SOURCE.read_text(encoding="utf-8"))
    lines = [
        f"# Generated by workflows/build/build_status_choices.py from {SOURCE.as_posix()}.",
        "# Do not edit by hand: change the input and re-run the builder.",
        f"name: {spec['name']}",
        "options:",
    ]
    for offset, label in enumerate(spec["labels"]):
        lines += [f"  - value: {FIRST_VALUE + offset}", f"    label: {label}"]
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
